1	import React, { useEffect, useState } from 'react';
2	import type { Feature } from '../../router/routes';
3	
4	// Projects feature: add a project and pick which client it is for, then list every project showing
5	// the client's NAME. Opening a project (project-open-<id>) reveals its detail: the invoices raised
6	// against it, their running total, and a form to add another. Owns its own state; talks to its own
7	// /api/projects and /api/invoices endpoints and reads /api/clients to populate the client picker.
8	// data-testid anchors follow the spec's conventions.
9	type Client = { id: number; name: string; email: string };
10	type Project = {
11	  id: number;
12	  name: string;
13	  clientId: number;
14	  clientName: string;
15	  archived: boolean;
16	};
17	type Invoice = {
18	  id: number;
19	  projectId: number;
20	  amount: number;
21	  status: string;
22	  issuedDate: string;
23	  dueDate: string;
24	};
25	type Task = { id: number; projectId: number; title: string; done: boolean };
26	type Tag = { id: number; name: string };
27	type Note = { id: number; targetType: string; targetId: number; text: string; at: string };
28	
29	type LineItem = {
30	  id: number;
31	  invoiceId: number;
32	  description: string;
33	  qty: number;
34	  unitPrice: number;
35	};
36	
37	type Payment = { id: number; invoiceId: number; amount: number; date: string };
38	
39	function money(amount: number): string {
40	  return `$${Number(amount).toFixed(2)}`;
41	}
42	
43	// One charge line while it is being edited on screen: the fields are held as raw strings so the
44	// inputs stay controlled and the total can recompute live as they change.
45	type EditItem = { id: number; description: string; qty: string; unitPrice: string };
46	
47	// An opened invoice's detail: the things it is charging for, listed as line items (description, how
48	// many, price each), the total worked out for you, and a form to add another line. Each line can be
49	// changed in place (save) or removed, and the total re-derives from whatever lines remain. Owns its
50	// own line-item state, scoped to the one invoice it is showing.
51	function InvoiceDetail({
52	  invoiceId,
53	  onChange,
54	  onClose,
55	}: {
56	  invoiceId: number;
57	  onChange: () => void;
58	  onClose: () => void;
59	}) {
60	  const [items, setItems] = useState<EditItem[]>([]);
61	  const [description, setDescription] = useState('');
62	  const [qty, setQty] = useState('');
63	  const [unitPrice, setUnitPrice] = useState('');
64	  const [payments, setPayments] = useState<Payment[]>([]);
65	  const [paymentAmount, setPaymentAmount] = useState('');
66	  const [paymentDate, setPaymentDate] = useState('');
67	
68	  async function load() {
69	    const res = await fetch(`/api/invoices/${invoiceId}/line-items`);
70	    const rows: LineItem[] = await res.json();
71	    setItems(
72	      rows.map((li) => ({
73	        id: li.id,
74	        description: li.description,
75	        qty: String(li.qty),
76	        unitPrice: String(li.unitPrice),
77	      })),
78	    );
79	  }
80	
81	  async function loadPayments() {
82	    const res = await fetch(`/api/invoices/${invoiceId}/payments`);
83	    setPayments(await res.json());
84	  }
85	
86	  async function submitPayment(e: React.FormEvent) {
87	    e.preventDefault();
88	    const value = Number(paymentAmount);
89	    if (paymentAmount.trim() === '' || !Number.isFinite(value) || value <= 0) {
90	      return;
91	    }
92	    if (paymentDate.trim() === '') {
93	      return;
94	    }
95	    await fetch(`/api/invoices/${invoiceId}/payments`, {
96	      method: 'POST',
97	      headers: { 'Content-Type': 'application/json' },
98	      body: JSON.stringify({ amount: value, date: paymentDate }),
99	    });
100	    setPaymentAmount('');
101	    setPaymentDate('');
102	    await loadPayments();
103	  }
104	
105	  useEffect(() => {
106	    void load();
107	    void loadPayments();
108	  }, [invoiceId]);
109	
110	  function editField(id: number, field: 'description' | 'qty' | 'unitPrice', value: string) {
111	    setItems((prev) => prev.map((li) => (li.id === id ? { ...li, [field]: value } : li)));
112	  }
113	
114	  function amountOf(li: EditItem): number {
115	    const line = Number(li.qty) * Number(li.unitPrice);
116	    return Number.isFinite(line) ? line : 0;
117	  }
118	
119	  async function save(li: EditItem) {
120	    if (!li.description.trim() || li.qty.trim() === '' || li.unitPrice.trim() === '') {
121	      return;
122	    }
123	    await fetch(`/api/invoices/${invoiceId}/line-items/${li.id}/update`, {
124	      method: 'POST',
125	      headers: { 'Content-Type': 'application/json' },
126	      body: JSON.stringify({
127	        description: li.description,
128	        qty: Number(li.qty),
129	        unitPrice: Number(li.unitPrice),
130	      }),
131	    });
132	    await load();
133	    onChange();
134	  }
135	
136	  async function remove(id: number) {
137	    await fetch(`/api/invoices/${invoiceId}/line-items/${id}/remove`, { method: 'POST' });
138	    await load();
139	    onChange();
140	  }
141	
142	  async function submit(e: React.FormEvent) {
143	    e.preventDefault();
144	    if (!description.trim() || qty.trim() === '' || unitPrice.trim() === '') {
145	      return;
146	    }
147	    await fetch(`/api/invoices/${invoiceId}/line-items`, {
148	      method: 'POST',
149	      headers: { 'Content-Type': 'application/json' },
150	      body: JSON.stringify({
151	        description,
152	        qty: Number(qty),
153	        unitPrice: Number(unitPrice),
154	      }),
155	    });
156	    setDescription('');
157	    setQty('');
158	    setUnitPrice('');
159	    await load();
160	    onChange();
161	  }
162	
163	  const total = items.reduce((sum, li) => sum + amountOf(li), 0);
164	
165	  return (
166	    <section data-testid="invoice-detail">
167	      <button data-testid="invoice-detail-close" type="button" onClick={onClose}>
168	        Back to invoices
169	      </button>
170	
171	      <table data-testid="invoice-lineitems-table">
172	        <tbody>
173	          {items.map((li) => (
174	            <tr key={li.id} data-testid={`lineitem-row-${li.id}`}>
175	              <td>
176	                <input
177	                  data-testid="lineitem-description"
178	                  value={li.description}
179	                  onChange={(e) => editField(li.id, 'description', e.target.value)}
180	                />
181	              </td>
182	              <td>
183	                <input
184	                  data-testid="lineitem-qty"
185	                  value={li.qty}
186	                  onChange={(e) => editField(li.id, 'qty', e.target.value)}
187	                />
188	              </td>
189	              <td>
190	                <input
191	                  data-testid="lineitem-unitprice"
192	                  value={li.unitPrice}
193	                  onChange={(e) => editField(li.id, 'unitPrice', e.target.value)}
194	                />
195	              </td>
196	              <td data-testid="lineitem-amount">{money(amountOf(li))}</td>
197	              <td>
198	                <button
199	                  data-testid={`lineitem-save-${li.id}`}
200	                  type="button"
201	                  onClick={() => save(li)}
202	                >
203	                  Save
204	                </button>
205	                <button
206	                  data-testid={`lineitem-remove-${li.id}`}
207	                  type="button"
208	                  onClick={() => remove(li.id)}
209	                >
210	                  Remove
211	                </button>
212	              </td>
213	            </tr>
214	          ))}
215	        </tbody>
216	      </table>
217	
218	      <p data-testid="invoice-amount">{money(total)}</p>
219	
220	      <form data-testid="lineitem-form" onSubmit={submit}>
221	        <input
222	          data-testid="lineitem-form-description"
223	          placeholder="Description"
224	          value={description}
225	          onChange={(e) => setDescription(e.target.value)}
226	        />
227	        <input
228	          data-testid="lineitem-form-qty"
229	          placeholder="How many"
230	          value={qty}
231	          onChange={(e) => setQty(e.target.value)}
232	        />
233	        <input
234	          data-testid="lineitem-form-unitprice"
235	          placeholder="Price each"
236	          value={unitPrice}
237	          onChange={(e) => setUnitPrice(e.target.value)}
238	        />
239	        <button data-testid="lineitem-form-submit" type="submit">
240	          Add line item
241	        </button>
242	      </form>
243	
244	      <table data-testid="invoice-payments-table">
245	        <tbody>
246	          {payments.map((p) => (
247	            <tr key={p.id} data-testid={`payment-row-${p.id}`}>
248	              <td data-testid="payment-amount">{money(p.amount)}</td>
249	              <td data-testid="payment-date">{p.date}</td>
250	            </tr>
251	          ))}
252	        </tbody>
253	      </table>
254	
255	      <form data-testid="payment-form" onSubmit={submitPayment}>
256	        <input
257	          data-testid="payment-form-amount"
258	          placeholder="Amount paid"
259	          value={paymentAmount}
260	          onChange={(e) => setPaymentAmount(e.target.value)}
261	        />
262	        <input
263	          data-testid="payment-form-date"
264	          type="date"
265	          value={paymentDate}
266	          onChange={(e) => setPaymentDate(e.target.value)}
267	        />
268	        <button data-testid="payment-form-submit" type="submit">
269	          Record payment
270	        </button>
271	      </form>
272	    </section>
273	  );
274	}
275	
276	// A project's detail: its invoices, what they add up to, and a form to add a new invoice. Owns its
277	// own invoice state, scoped to the one project it is showing.
278	function ProjectDetail({ project }: { project: Project }) {
279	  const [invoices, setInvoices] = useState<Invoice[]>([]);
280	  const [tasks, setTasks] = useState<Task[]>([]);
281	  const [tags, setTags] = useState<Tag[]>([]);
282	  const [allTags, setAllTags] = useState<Tag[]>([]);
283	  const [tagToAdd, setTagToAdd] = useState('');
284	  const [taskFilter, setTaskFilter] = useState<'ALL' | 'OPEN' | 'DONE'>('ALL');
285	  const [amount, setAmount] = useState('');
286	  const [amountError, setAmountError] = useState('');
287	  const [sortByDue, setSortByDue] = useState(false);
288	  const [openInvoiceId, setOpenInvoiceId] = useState<number | null>(null);
289	  const [notes, setNotes] = useState<Note[]>([]);
290	  const [noteText, setNoteText] = useState('');
291	
292	  async function load() {
293	    const res = await fetch(`/api/invoices?projectId=${project.id}`);
294	    setInvoices(await res.json());
295	  }
296	
297	  async function loadNotes() {
298	    const res = await fetch(`/api/notes?targetType=project&targetId=${project.id}`);
299	    setNotes(await res.json());
300	  }
301	
302	  async function submitNote(e: React.FormEvent) {
303	    e.preventDefault();
304	    if (!noteText.trim()) {
305	      return;
306	    }
307	    await fetch('/api/notes', {
308	      method: 'POST',
309	      headers: { 'Content-Type': 'application/json' },
310	      body: JSON.stringify({ targetType: 'project', targetId: project.id, text: noteText }),
311	    });
312	    setNoteText('');
313	    await loadNotes();
314	  }
315	
316	  async function loadTasks() {
317	    const res = await fetch(`/api/tasks?projectId=${project.id}`);
318	    setTasks(await res.json());
319	  }
320	
321	  async function loadTags() {
322	    const [mine, all] = await Promise.all([
323	      fetch(`/api/projects/${project.id}/tags`).then((r) => r.json()),
324	      fetch('/api/tags').then((r) => r.json()),
325	    ]);
326	    setTags(mine);
327	    setAllTags(all);
328	  }
329	
330	  useEffect(() => {
331	    void load();
332	    void loadTasks();
333	    void loadTags();
334	    void loadNotes();
335	  }, [project.id]);
336	
337	  async function toggleTask(id: number) {
338	    await fetch(`/api/tasks/${id}/toggle`, { method: 'POST' });
339	    await loadTasks();
340	  }
341	
342	  async function addTag(e: React.FormEvent) {
343	    e.preventDefault();
344	    if (!tagToAdd) {
345	      return;
346	    }
347	    await fetch(`/api/projects/${project.id}/tags`, {
348	      method: 'POST',
349	      headers: { 'Content-Type': 'application/json' },
350	      body: JSON.stringify({ tagId: Number(tagToAdd) }),
351	    });
352	    setTagToAdd('');
353	    await loadTags();
354	  }
355	
356	  async function removeTag(id: number) {
357	    await fetch(`/api/projects/${project.id}/tags/${id}/remove`, { method: 'POST' });
358	    await loadTags();
359	  }
360	
361	  async function submit(e: React.FormEvent) {
362	    e.preventDefault();
363	    const value = Number(amount);
364	    if (amount.trim() === '' || !Number.isFinite(value) || value <= 0) {
365	      setAmountError('Amount must be more than zero');
366	      return;
367	    }
368	    setAmountError('');
369	    await fetch('/api/invoices', {
370	      method: 'POST',
371	      headers: { 'Content-Type': 'application/json' },
372	      body: JSON.stringify({ projectId: project.id, amount: Number(amount) }),
373	    });
374	    setAmount('');
375	    await load();
376	  }
377	
378	  async function send(id: number) {
379	    await fetch(`/api/invoices/${id}/send`, { method: 'POST' });
380	    await load();
381	  }
382	
383	  async function pay(id: number) {
384	    await fetch(`/api/invoices/${id}/pay`, { method: 'POST' });
385	    await load();
386	  }
387	
388	  const shownTasks = tasks.filter((t) =>
389	    taskFilter === 'OPEN' ? !t.done : taskFilter === 'DONE' ? t.done : true,
390	  );
391	
392	  const total = invoices.reduce((sum, inv) => sum + Number(inv.amount), 0);
393	  const shownInvoices = sortByDue
394	    ? [...invoices].sort((a, b) => a.dueDate.localeCompare(b.dueDate))
395	    : invoices;
396	
397	  return (
398	    <section data-testid="project-detail">
399	      <h2 data-testid="project-detail-name">{project.name}</h2>
400	
401	      <div data-testid="project-tags">
402	        {tags.map((tag) => (
403	          <span key={tag.id}>
404	            <span data-testid={`project-tag-${tag.id}`}>{tag.name}</span>
405	            <button
406	              data-testid={`project-tag-remove-${tag.id}`}
407	              type="button"
408	              onClick={() => removeTag(tag.id)}
409	            >
410	              Remove
411	            </button>
412	          </span>
413	        ))}
414	      </div>
415	
416	      <form data-testid="project-tag-form" onSubmit={addTag}>
417	        <select
418	          data-testid="project-tag-add"
419	          value={tagToAdd}
420	          onChange={(e) => setTagToAdd(e.target.value)}
421	        >
422	          <option value="">Add a label</option>
423	          {allTags
424	            .filter((t) => !tags.some((mine) => mine.id === t.id))
425	            .map((t) => (
426	              <option key={t.id} value={String(t.id)}>
427	                {t.name}
428	              </option>
429	            ))}
430	        </select>
431	        <button data-testid="project-tag-add-submit" type="submit">
432	          Add label
433	        </button>
434	      </form>
435	
436	      <select
437	        data-testid="task-filter"
438	        value={taskFilter}
